-- +goose Up
-- Every table carries workspace_id so data can later be sharded by workspace.
-- IDs are UUIDv7 (time-ordered), generated by Postgres 18's uuidv7().

CREATE TABLE workspaces (
    id         uuid PRIMARY KEY DEFAULT uuidv7(),
    name       text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

-- The MVP has no sign-in: everything belongs to this workspace.
INSERT INTO workspaces (id, name) VALUES ('01900000-0000-7000-8000-000000000001', 'Default workspace');

CREATE TABLE meetings (
    id                 uuid PRIMARY KEY DEFAULT uuidv7(),
    workspace_id       uuid NOT NULL REFERENCES workspaces (id),
    title              text NOT NULL,
    participants       text[] NOT NULL DEFAULT '{}',
    idempotency_key    text,
    status             text NOT NULL CHECK (status IN ('recording', 'queued', 'transcribing', 'summarizing', 'ready', 'failed')),
    error              text,
    duration_ms        bigint,
    audio_key          text,
    audio_content_type text,
    audio_size         bigint,
    started_at         timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX meetings_workspace_id_idx ON meetings (workspace_id, id DESC);
CREATE UNIQUE INDEX meetings_idempotency_uq ON meetings (workspace_id, idempotency_key) WHERE idempotency_key IS NOT NULL;

-- One transcript document per meeting: written once per run, read whole.
CREATE TABLE transcripts (
    meeting_id   uuid PRIMARY KEY REFERENCES meetings (id) ON DELETE CASCADE,
    workspace_id uuid NOT NULL REFERENCES workspaces (id),
    language     text NOT NULL,
    segments     jsonb NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE summaries (
    meeting_id    uuid PRIMARY KEY REFERENCES meetings (id) ON DELETE CASCADE,
    workspace_id  uuid NOT NULL REFERENCES workspaces (id),
    overview      text NOT NULL,
    takeaways     jsonb NOT NULL DEFAULT '[]',
    decisions     jsonb NOT NULL DEFAULT '[]',
    questions     jsonb NOT NULL DEFAULT '[]',
    provider      text NOT NULL,
    model         text,
    input_tokens  bigint,
    output_tokens bigint,
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE action_items (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    meeting_id   uuid NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
    workspace_id uuid NOT NULL REFERENCES workspaces (id),
    position     integer NOT NULL,
    text         text NOT NULL,
    owner        text,
    due          text,
    done         boolean NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX action_items_meeting_idx ON action_items (meeting_id, position);

-- +goose Down
DROP TABLE action_items;
DROP TABLE summaries;
DROP TABLE transcripts;
DROP TABLE meetings;
DROP TABLE workspaces;
